  const [activeSettingsTab, setActiveSettingsTab] = useState<string>('General');

  // Developer Mode state (disabled by default, session-validated via backend)
  const [isDeveloperMode, setIsDeveloperMode] = useState<boolean>(() => {
    return Boolean(getDeveloperToken());
  });
  const [showDevModeModal, setShowDevModeModal] = useState<boolean>(false);

  // Sync Developer Mode state with custom events
  useEffect(() => {
    const onUnlocked = () => setIsDeveloperMode(true);
    const onLocked = () => {
      setIsDeveloperMode(false);
      if (activeSettingsTab === 'Module Management' || activeSettingsTab === 'Payment Integrations') {
        setActiveSettingsTab('General');
      }
    };
    window.addEventListener('developer_mode_unlocked', onUnlocked);
    window.addEventListener('developer_mode_locked', onLocked);
    return () => {
      window.removeEventListener('developer_mode_unlocked', onUnlocked);
      window.removeEventListener('developer_mode_locked', onLocked);
    };
  }, [activeSettingsTab]);

  // Global Developer Mode shortcut: Ctrl + Shift + D (or Ctrl + Alt + D / Cmd on Mac)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const isCtrlOrCmd = e.ctrlKey || e.metaKey;
      const isShift = e.shiftKey;
      const isAlt = e.altKey;
      const isKeyD = e.code === 'KeyD' || e.key === 'd' || e.key === 'D';

      if (isCtrlOrCmd && (isShift || isAlt) && isKeyD) {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation?.();
        setShowDevModeModal(true);
      }
    };

    window.addEventListener('keydown', handleKeyDown, true);
    document.addEventListener('keydown', handleKeyDown, true);
    return () => {
      window.removeEventListener('keydown', handleKeyDown, true);
      document.removeEventListener('keydown', handleKeyDown, true);
    };
  }, []);

  // Strict guard: If Developer Mode is OFF, ensure Module Management or Payment Integrations tabs are never active
  useEffect(() => {
    if (!isDeveloperMode && (activeSettingsTab === 'Module Management' || activeSettingsTab === 'Payment Integrations')) {
      setActiveSettingsTab('General');
    }
  }, [isDeveloperMode, activeSettingsTab]);

  const currentUserRoleKey = useMemo<'owner' | 'manager' | 'cashier'>(() => {
    const r = String(user?.role || '').toLowerCase();
    if (r === 'owner' || r === 'admin' || r === 'super_admin') return 'owner';
    if (r === 'manager' || r === 'store_manager') return 'manager';
    return 'cashier';
  }, [user?.role]);

  const isModuleVisible = useCallback(
    (moduleKey: string) => {
      return isModuleEnabledForRole(moduleAccessConfig, currentUserRoleKey, moduleKey);
    },
    [moduleAccessConfig, currentUserRoleKey]
  );

  useEffect(() => {
    let active = true;
    if (user) {
      fetchModuleAccess()
        .then((res) => {
          if (active && res?.access) {
            setModuleAccessConfig(res.access);
          }
        })
        .catch((err) => {
          console.warn('[App] Could not fetch module access config:', err);
        });
    }
    return () => {
      active = false;
    };
  }, [user]);

  const [selectedBranchScope, setSelectedBranchScope] = useState<string>(() => {
    if (user && user.role !== 'owner' && String(user.role).toUpperCase() !== 'SUPER_ADMIN') {
      const enforced = user.branchId || (user as any).branch_id || user.assignedLocation;
      if (enforced) return enforced;
    }
    return getActiveBranchScope();
  });

  // Ensure non-superadmin accounts (Store Managers, Cashiers) are strictly locked to their assigned branch
  useEffect(() => {
    if (!user) return;
    const isSuperAdmin = user.role === 'owner' || String(user.role).toUpperCase() === 'SUPER_ADMIN';
    if (!isSuperAdmin) {
      const enforced = user.branchId || (user as any).branch_id || user.assignedLocation;
      if (enforced && selectedBranchScope !== enforced) {
        setSelectedBranchScope(enforced);
        try {
          localStorage.setItem('sa_selected_branch', enforced);
          localStorage.setItem('selected_branch', enforced);
          sessionStorage.setItem('sa_selected_branch', enforced);
          sessionStorage.setItem('selected_branch', enforced);
        } catch { }
      }
    }
  }, [user?.id, user?.branchId, user?.role, selectedBranchScope]);

  // Day Closing Overdue Alert state for top global header bar
  const [topOverdueClosing, setTopOverdueClosing] = useState<{
    isOverdue: boolean;
    expectedClosingTime: string;
    minutesOverdue: number;
  } | null>(null);

  useEffect(() => {
    let isMounted = true;
    const checkTopOverdue = async () => {
      try {
        if (!getToken() || !user) return;
        const branch = selectedBranchScope || 'MAIN';
        const res = await fetchDayClosingCompliance({ branchId: branch });
        if (isMounted) {
          const isClosed = Boolean(
            res.summary?.isStoreClosed ||
            res.summary?.storeStatus === 'approved' ||
            res.summary?.storeStatus === 'closed' ||
            res.summary?.storeStatus === 'submitted'
          );
          if (res.success && res.isBranchOverdue && !isClosed) {
            setTopOverdueClosing({
              isOverdue: true,
              expectedClosingTime: res.expectedClosingTime || '22:00',
              minutesOverdue: res.minutesOverdue || 0,
            });
          } else {
            setTopOverdueClosing(null);
          }
        }
      } catch {
        // background silent catch
      }
    };

    checkTopOverdue();
    const interval = setInterval(checkTopOverdue, 30000);
    const onClosingUpdated = () => checkTopOverdue();
    window.addEventListener('day_closing_updated', onClosingUpdated);
    window.addEventListener('day_closing_submitted', onClosingUpdated);

    return () => {
      isMounted = false;
      clearInterval(interval);
      window.removeEventListener('day_closing_updated', onClosingUpdated);
      window.removeEventListener('day_closing_submitted', onClosingUpdated);
    };
  }, [selectedBranchScope]);

  // Real-time Cashier Shift & Day Closing notifications state
  const [shiftNotifications, setShiftNotifications] = useState<any[]>([]);
  const [unreadShiftNotifCount, setUnreadShiftNotifCount] = useState<number>(0);

  const loadNotifications = useCallback(async () => {
    if (!user || user.role === 'cashier') return;
    try {
      const activeBranch = selectedBranchScope && selectedBranchScope.toLowerCase() !== 'all' ? selectedBranchScope : undefined;
      const res = await fetchDayClosingNotifications({ branchId: activeBranch });
      if (res && res.success) {
        setShiftNotifications(res.notifications || []);
        setUnreadShiftNotifCount(res.unreadCount || 0);
      }
    } catch (err) {
      console.error('Error fetching shift notifications:', err);
    }
  }, [user, selectedBranchScope]);

  useEffect(() => {
    if (!user || user.role === 'cashier') return;
    loadNotifications();
    const interval = setInterval(loadNotifications, 15000);
    const onShiftEvent = () => loadNotifications();
    window.addEventListener('shift_opened', onShiftEvent);
    window.addEventListener('shift_closed', onShiftEvent);
    window.addEventListener('shift_status_changed', onShiftEvent);
    window.addEventListener('shift_updated', onShiftEvent);
    window.addEventListener('day_closing_updated', onShiftEvent);
    window.addEventListener('day_closing_submitted', onShiftEvent);
    window.addEventListener('focus', onShiftEvent);

    return () => {
      clearInterval(interval);
      window.removeEventListener('shift_opened', onShiftEvent);
      window.removeEventListener('shift_closed', onShiftEvent);
      window.removeEventListener('shift_status_changed', onShiftEvent);
      window.removeEventListener('shift_updated', onShiftEvent);
      window.removeEventListener('day_closing_updated', onShiftEvent);
      window.removeEventListener('day_closing_submitted', onShiftEvent);
      window.removeEventListener('focus', onShiftEvent);
    };
  }, [user, loadNotifications]);

  const handleMarkAllNotificationsRead = async () => {
    try {
      const unreadIds = shiftNotifications
        .filter((n) => !n.isRead && !n.is_read)
        .map((n) => n.id)
        .filter(Boolean);
      await markAllDayClosingNotificationsRead(unreadIds.length > 0 ? unreadIds : undefined);
      setShiftNotifications((prev) =>
        prev.map((n) => ({ ...n, is_read: true, isRead: true }))
      );
      setUnreadShiftNotifCount(0);
    } catch (err) {
      console.error('Failed to mark all notifications read:', err);
    }
  };

  const handleNotificationClick = async (notif: any) => {
    try {
      if (!notif.is_read && !notif.isRead) {
        await markDayClosingNotificationRead(notif.id);
        setShiftNotifications((prev) =>
          prev.map((n) => (n.id === notif.id ? { ...n, is_read: true, isRead: true } : n))
        );
        setUnreadShiftNotifCount((prev) => Math.max(0, prev - 1));
      }
    } catch (err) {
      console.error('Failed to mark notification read:', err);
    }
  };

  const formatNotifTimeAgo = (dateStr?: string) => {
    if (!dateStr) return 'Just now';
    const time = new Date(dateStr).getTime();
    if (isNaN(time)) return 'Just now';
    const diff = Math.max(0, Date.now() - time);
    const mins = Math.floor(diff / 60000);
    if (mins < 1) return 'Just now';
    if (mins < 60) return `${mins}m ago`;
    const hours = Math.floor(mins / 60);
    if (hours < 24) return `${hours}h ago`;
    const days = Math.floor(hours / 24);
    return `${days}d ago`;
  };

  const handleGlobalBranchChange = async (newBranchCode: string) => {
    const normalized = (newBranchCode || 'all').trim();
    setSelectedBranchScope(normalized);
    setActiveBranchScope(normalized);
    setInvoiceBranchFilter(normalized);

    const isAll = normalized.toLowerCase() === 'all';
    const match = !isAll
      ? branches.find((b) => b.id === normalized || (b.code && b.code.toUpperCase() === normalized.toUpperCase()))
      : null;

    const detail = {
      branch: normalized,
      branchId: match ? match.id : isAll ? null : normalized,
      branchCode: match ? match.code : isAll ? 'ALL' : normalized.toUpperCase(),
      branchName: match ? match.name : isAll ? 'All Branches (Overall)' : normalized,
    };

    window.dispatchEvent(new CustomEvent('branch_scope_changed', { detail }));

    try {
      await Promise.allSettled([
        loadInvoices(),
        loadReports(newBranchCode),
        loadItems(),
        loadCategories(),
        loadPurchases(),
        loadParties(),
        loadDuesSummary(),
        loadActivePromotions(),
      ]);
    } catch (err) {
      console.error('[BranchScope] Error refreshing branch collections:', err);
    }
  };

  const activeBranch = useMemo(() => {
    if (isSuperAdminUser) {
      if (!selectedBranchScope || selectedBranchScope.toLowerCase() === 'all') {
        return null;
      }
      return (
        branches.find(
          (b) =>
            b.id === selectedBranchScope ||
            (b.code && b.code.toUpperCase() === selectedBranchScope.toUpperCase())
        ) || null
      );
    }
    return (
      branches.find(
        (b) =>
          b.id === user?.branchId ||
          (b.code && b.code.toUpperCase() === (user?.branchId || user?.assignedLocation || '').toUpperCase())
      ) || null
    );
  }, [isSuperAdminUser, selectedBranchScope, branches, user]);

  const currentBranchName = activeBranch
    ? activeBranch.name
    : (!selectedBranchScope || selectedBranchScope.toLowerCase() === 'all'
      ? 'All Branches (Overall)'
      : user?.assignedLocation || shop?.name || 'Main Branch');
  const currentBranchCode = activeBranch
    ? activeBranch.code || 'MAIN'
    : (!selectedBranchScope || selectedBranchScope.toLowerCase() === 'all'
      ? 'ALL'
      : 'MAIN');
  const [activePromotionsList, setActivePromotionsList] = useState<Promotion[]>([]);
  const [promoEvalResult, setPromoEvalResult] = useState<PromotionEvalResult | null>(null);
  const catalogSearchInputRef = useRef<HTMLInputElement>(null);
  const customerMobileInputRef = useRef<HTMLInputElement>(null);
  const customerNameInputRef = useRef<HTMLInputElement>(null);
  const customerNameManuallyEditedRef = useRef(false);
  const manuallyDecreasedItemsRef = useRef<Set<string>>(new Set());
  const checkoutBtnRef = useRef<HTMLButtonElement>(null);
  const [catalogSelectedIndex, setCatalogSelectedIndex] = useState<number>(-1);
  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [printModalInvoiceId, setPrintModalInvoiceId] = useState<string | null>(null);

  // Barcode Label Printing & Toggle State
  const [activePrintLabels, setActivePrintLabels] = useState<Array<{ name: string; sku?: string | null; barcode: string; priceMinor?: number }> | null>(null);
  const [printBarcodeItem, setPrintBarcodeItem] = useState<Item | null>(null);
  const [showPrintBarcodeModal, setShowPrintBarcodeModal] = useState(false);
  const [showBulkBarcodeModal, setShowBulkBarcodeModal] = useState(false);
  const [showScanMfrModal, setShowScanMfrModal] = useState(false);
  const [scanMfrInitialItemId, setScanMfrInitialItemId] = useState<string | null>(null);
  const [togglingItemId, setTogglingItemId] = useState<string | null>(null);

  // Billing Counter State
  const [selectedCounter, setSelectedCounter] = useState<string>(() => {
    try {
      const saved = sessionStorage.getItem('pos_selected_counter') || localStorage.getItem('pos_selected_counter') || '';
      if (saved.toUpperCase().includes('ADMIN') || saved.toUpperCase().includes('MGR')) {
        return '';
      }
      return saved;
    } catch {
      return '';
    }
  });
  const [selectedCounterId, setSelectedCounterId] = useState<string>(() => {
    try {
      const saved = sessionStorage.getItem('pos_selected_counter_id') || localStorage.getItem('pos_selected_counter_id') || '';
      if (saved.toUpperCase().includes('ADMIN') || saved.toUpperCase().includes('MGR')) {
        return '';
      }
      return saved;
    } catch {
      return '';
    }
  });

  // Wireless Mobile Barcode Scanner State: strictly scoped per branch & counter station
  const scannerSessionId = useMemo(() => {
    const rawBranch = (currentBranchCode && currentBranchCode !== 'ALL' ? currentBranchCode : activeBranch?.code || 'main')
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9_-]/g, '-');
    const rawCounter = (selectedCounter || 'c01')
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9_-]/g, '-');
    return `pos-${rawBranch}-${rawCounter}`;
  }, [currentBranchCode, activeBranch?.code, selectedCounter]);
  const [showMobileScannerModal, setShowMobileScannerModal] = useState(false);
  const [isPhoneScannerConnected, setIsPhoneScannerConnected] = useState(false);
  type ScannerConnectionStatus = 'waiting' | 'phone_connected' | 'scanner_ready' | 'connection_lost' | 'unable_to_connect';
  const [scannerStatus, setScannerStatus] = useState<ScannerConnectionStatus>('waiting');
  const [externalBarcodeScan, setExternalBarcodeScan] = useState<{ barcode: string; timestamp: number } | null>(null);
  // Inline POS Camera Scanner States
  const [isPosCameraActive, setIsPosCameraActive] = useState(false);
  const [isPosCameraStarting, setIsPosCameraStarting] = useState(false);
  const [posCameraError, setPosCameraError] = useState<string | null>(null);
  const [posCameraDevices, setPosCameraDevices] = useState<Array<{ id: string; label: string }>>([]);
  const [selectedPosCameraId, setSelectedPosCameraId] = useState<string | null>(null);
  const [cameraScanFlash, setCameraScanFlash] = useState(false);
  const posHtml5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const isPosCameraStartingRef = useRef(false);
  const lastCameraScanRef = useRef<{ code: string; time: number } | null>(null);
  const [scannerNetworkInfo, setScannerNetworkInfo] = useState<{
    localIp: string;
    lanIp?: string;
    isLanAvailable?: boolean;
    lanIps?: string[];
    publicIps?: string[];
    allIps?: string[];
    httpPort: number;
    httpsPort: number;
    tunnelUrl?: string;
    isTunnelAlive?: boolean;
    tunnelStatus?: string;
    tunnelError?: string;
  } | null>(null);
  const [scannerProtocol, setScannerProtocol] = useState<'tunnel' | 'wifi' | 'https' | 'server'>('tunnel');
  const [scannerSoundEnabled, setScannerSoundEnabled] = useState(true);
  const [customTunnelUrl, setCustomTunnelUrl] = useState('');
  const [showCfdModal, setShowCfdModal] = useState(false);
  const [isCfdConnected, setIsCfdConnected] = useState(false);

  const scannerPairingUrl = useMemo(() => {
    const counterParam = encodeURIComponent(selectedCounter || 'Counter 1');
    const port = scannerNetworkInfo?.httpPort || (typeof window !== 'undefined' && window.location.port ? Number(window.location.port) : 3001);
    const httpsPort = scannerNetworkInfo?.httpsPort || (port + 443);
    const lanIp = scannerNetworkInfo?.lanIp || scannerNetworkInfo?.localIp || '';
    const isLiveOrigin = typeof window !== 'undefined' && window.location.hostname !== 'localhost' && window.location.hostname !== '127.0.0.1';

    let base = '';
    if (customTunnelUrl.trim()) {
      base = customTunnelUrl.trim().replace(/\/+$/, '');
    } else if (scannerProtocol === 'tunnel') {
      if (scannerNetworkInfo?.tunnelUrl) {
        base = scannerNetworkInfo.tunnelUrl.replace(/\/+$/, '');
      } else if (isLiveOrigin) {
        base = window.location.origin.replace(/\/+$/, '');
      } else if (lanIp && lanIp !== 'localhost' && lanIp !== '127.0.0.1') {
        base = `http://${lanIp}:${port}`;
      } else {
        base = window.location.origin.replace(/\/+$/, '');
      }
    } else if (scannerProtocol === 'server') {
      base = isLiveOrigin ? window.location.origin.replace(/\/+$/, '') : (lanIp && lanIp !== 'localhost' ? `http://${lanIp}:${port}` : window.location.origin.replace(/\/+$/, ''));
    } else if (scannerProtocol === 'https') {
      base = `https://${lanIp || window.location.hostname}:${httpsPort}`;
    } else {
      // 'wifi'
      base = lanIp && lanIp !== 'localhost' && lanIp !== '127.0.0.1'
        ? `http://${lanIp}:${port}`
        : window.location.origin.replace(/\/+$/, '');
    }
    return `${base}/scanner?session=${encodeURIComponent(scannerSessionId)}&counter=${counterParam}`;
  }, [scannerNetworkInfo, scannerProtocol, customTunnelUrl, scannerSessionId, selectedCounter]);

  // Modern Image 2 POS State
  const [customerSearch, setCustomerSearch] = useState(() => {
    try {
      return localStorage.getItem('pos_draft_customer_search') || '';
    } catch {
      return '';
    }
  });
  useEffect(() => {
    try {
      if (customerSearch) {
        localStorage.setItem('pos_draft_customer_search', customerSearch);
      } else {
        localStorage.removeItem('pos_draft_customer_search');
      }
    } catch { }
  }, [customerSearch]);

  const [quickCustomerName, setQuickCustomerName] = useState(() => {
    try {
      return localStorage.getItem('pos_draft_customer_name') || '';
    } catch {
      return '';
    }
  });
  useEffect(() => {
    try {
      if (quickCustomerName) {
        localStorage.setItem('pos_draft_customer_name', quickCustomerName);
      } else {
        localStorage.removeItem('pos_draft_customer_name');
      }
    } catch { }
  }, [quickCustomerName]);

  const [isQuickEnrolling, setIsQuickEnrolling] = useState(false);
  const [showCustomerDropdown, setShowCustomerDropdown] = useState(false);
  const [showCustomerPickerModal, setShowCustomerPickerModal] = useState(false);
  const [redeemPoints, setRedeemPoints] = useState(false);
  const [appliedDiscountPercent, setAppliedDiscountPercent] = useState<number>(() => {
    try {
      const saved = localStorage.getItem('pos_draft_discount');
      if (saved) {
        const num = Number(saved);
        if (!isNaN(num) && num >= 0 && num <= 100) return num;
      }
    } catch { }
    return 0;
  });
  useEffect(() => {
    try {
      if (appliedDiscountPercent > 0) {
        localStorage.setItem('pos_draft_discount', String(appliedDiscountPercent));
      } else {
        localStorage.removeItem('pos_draft_discount');
      }
    } catch { }
  }, [appliedDiscountPercent]);
  const [showDiscountPicker, setShowDiscountPicker] = useState(false);
  const [showPosOpenShiftModal, setShowPosOpenShiftModal] = useState(false);
  const [showCounterModal, setShowCounterModal] = useState<boolean>(false);
  const [showLogoutShiftModal, setShowLogoutShiftModal] = useState<boolean>(false);
  const [showLogoutConfirmModal, setShowLogoutConfirmModal] = useState<boolean>(false);
  const [showHeldOrdersModal, setShowHeldOrdersModal] = useState(false);
  const [showCustomItemModal, setShowCustomItemModal] = useState(false);
  const [showShortcutsModal, setShowShortcutsModal] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState<boolean>(() => {
    try {
      const saved = localStorage.getItem('sidebarCollapsed');
      if (saved !== null) {
        return saved === 'true';
      }
    } catch { }
    return false;
  });

  const toggleSidebar = () => {
    setIsSidebarCollapsed(prev => {
      const next = !prev;
      try {
        localStorage.setItem('sidebarCollapsed', String(next));
      } catch { }
      return next;
    });
  };

  const [isMobileSidebarOpen, setIsMobileSidebarOpen] = useState(false);

  // Close mobile sidebar on route or tab change
  useEffect(() => {
    setIsMobileSidebarOpen(false);
  }, [activeTab, displayTab]);

  // Handle mobile drawer body scroll locking and Escape key
  useEffect(() => {
    if (isMobileSidebarOpen) {
      document.body.classList.add('mobile-drawer-open');
    } else {
      document.body.classList.remove('mobile-drawer-open');
    }
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setIsMobileSidebarOpen(false);
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      document.body.classList.remove('mobile-drawer-open');
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isMobileSidebarOpen]);

  const [autoCollapsedForPos, setAutoCollapsedForPos] = useState(false);
  const [showProductCatalogDrawer, setShowProductCatalogDrawer] = useState(false);
  const [selectedCartIndex, setSelectedCartIndex] = useState<number>(0);
  const [customItemForm, setCustomItemForm] = useState({ name: 'Custom Charge', price: '50', taxRateBp: 1800 });
  const [heldOrders, setHeldOrders] = useState<{ id: string; cart: { item: Item; qty: number }[]; timestamp: Date }[]>(() => {
    try {
      const saved = localStorage.getItem('pos_held_orders');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          return parsed.map((o: any) => ({ ...o, timestamp: new Date(o.timestamp) }));
        }
      }
    } catch { }
    return [];
  });

  useEffect(() => {
    try {
      localStorage.setItem('pos_held_orders', JSON.stringify(heldOrders));
    } catch { }
  }, [heldOrders]);

  useEffect(() => {
    if (activeTab === 'pos') {
      try {
        // POS Counter defaults to collapsed on first visit if user has not set a preference
        if (localStorage.getItem('sidebarCollapsed') === null && !isSidebarCollapsed) {
          setIsSidebarCollapsed(true);
        }
      } catch { }
    }
  }, [activeTab]);

  // Synchronize and validate counter station selection strictly scoped by role
  useEffect(() => {
    if (!activeBranch || !activeBranch.counterDetails || activeBranch.counterDetails.length === 0) return;
    const activeList = activeBranch.counterDetails.filter((c: any) => c.status !== 'DISABLED');
    if (activeList.length === 0) return;

    // Super Admin: strictly locked to dedicated Admin Counter (never occupies cashier stations)
    if (user?.role === 'owner') {
      const adminMatch = activeList.find((c: any) => c.code.toUpperCase() === 'ADMIN-POS' || c.name.toLowerCase().includes('admin counter'));
      const targetCode = adminMatch?.code || 'ADMIN-POS';
      const targetId = adminMatch?.id || 'ADMIN-POS';
      if (selectedCounter !== targetCode || selectedCounterId !== targetId) {
        setSelectedCounter(targetCode);
        setSelectedCounterId(targetId);
      }
      return;
    }

    // Store Manager: strictly locked to dedicated Manager Counter for this branch (never occupies cashier stations)
    if (user?.role === 'manager') {
      const mgrMatch = activeList.find((c: any) => c.code.toUpperCase().includes('MGR') || c.name.toLowerCase().includes('manager counter'));
      const targetCode = mgrMatch?.code || `${currentBranchCode}-MGR`;
      const targetId = mgrMatch?.id || `${currentBranchCode}-MGR`;
      if (selectedCounter !== targetCode || selectedCounterId !== targetId) {
        setSelectedCounter(targetCode);
        setSelectedCounterId(targetId);
      }
      return;
    }

    // Cashier role: strictly limited to cashier stations (exclude Admin & Manager counters)
    const cashierCounters = activeList.filter(
      (c: any) => c.code !== 'ADMIN-POS' && !c.code.includes('MGR') && !c.name.toLowerCase().includes('admin') && !c.name.toLowerCase().includes('manager')
    );

    // If current selectedCounter or selectedCounterId is contaminated with Admin or Manager counters, purge immediately
    const isDirtyAdminOrMgr =
      selectedCounter.toUpperCase().includes('ADMIN') ||
      selectedCounter.toUpperCase().includes('MGR') ||
      selectedCounterId.toUpperCase().includes('ADMIN') ||
      selectedCounterId.toUpperCase().includes('MGR');

    if (isDirtyAdminOrMgr) {
      try {
        sessionStorage.removeItem('pos_selected_counter_id');
        sessionStorage.removeItem('pos_selected_counter');
        sessionStorage.removeItem('pos_selected_counter_name');
        localStorage.removeItem('pos_selected_counter_id');
        localStorage.removeItem('pos_selected_counter');
        localStorage.removeItem('pos_selected_counter_name');
      } catch { }
    }

    const curId = isDirtyAdminOrMgr ? '' : selectedCounterId;
    const curCode = isDirtyAdminOrMgr ? '' : selectedCounter;

    if (curId) {
      const match = cashierCounters.find((c: any) => c.id === curId);
      if (!match) {
        // Counter ID does not belong to active branch cashier stations -> fallback to default
        const defaultCounter = cashierCounters[0];
        if (defaultCounter) {
          setSelectedCounterId(defaultCounter.id);
          setSelectedCounter(defaultCounter.code);
          try {
            sessionStorage.setItem('pos_selected_counter_id', defaultCounter.id);
            sessionStorage.setItem('pos_selected_counter', defaultCounter.code);
            localStorage.setItem('pos_selected_counter_id', defaultCounter.id);
            localStorage.setItem('pos_selected_counter', defaultCounter.code);
          } catch { }
        } else {
          setSelectedCounterId('');
          setSelectedCounter('');
        }
        setShowCounterModal(true);
      } else {
        if (match.code !== selectedCounter) {
          setSelectedCounter(match.code);
          try {
            sessionStorage.setItem('pos_selected_counter', match.code);
            localStorage.setItem('pos_selected_counter', match.code);
          } catch { }
        }
        // Ensure backend immediately registers this station as occupied by the current cashier
        selectActiveShiftCounter({
          counterId: match.id,
          counter: match.code,
          branchId: activeBranch.id,
        }).catch((err: any) => {
          if (err?.code === 'COUNTER_OCCUPIED') {
            setSelectedCounterId('');
            setSelectedCounter('');
            setShowCounterModal(true);
          }
        });
      }
    } else if (curCode) {
      const match = cashierCounters.find((c: any) => c.code.toUpperCase() === curCode.toUpperCase() || c.name.toLowerCase() === curCode.toLowerCase());
      if (match) {
        setSelectedCounterId(match.id);
        setSelectedCounter(match.code);
        try {
          sessionStorage.setItem('pos_selected_counter_id', match.id);
          sessionStorage.setItem('pos_selected_counter', match.code);
          localStorage.setItem('pos_selected_counter_id', match.id);
          localStorage.setItem('pos_selected_counter', match.code);
        } catch { }
        selectActiveShiftCounter({
          counterId: match.id,
          counter: match.code,
          branchId: activeBranch.id,
        }).catch((err: any) => {
          if (err?.code === 'COUNTER_OCCUPIED') {
            setSelectedCounterId('');
            setSelectedCounter('');
            setShowCounterModal(true);
          }
        });
      } else {
        const defaultCounter = cashierCounters[0];
        if (defaultCounter) {
          setSelectedCounterId(defaultCounter.id);
          setSelectedCounter(defaultCounter.code);
          try {
            sessionStorage.setItem('pos_selected_counter_id', defaultCounter.id);
            sessionStorage.setItem('pos_selected_counter', defaultCounter.code);
            localStorage.setItem('pos_selected_counter_id', defaultCounter.id);
            localStorage.setItem('pos_selected_counter', defaultCounter.code);
          } catch { }
        } else {
          setSelectedCounterId('');
          setSelectedCounter('');
        }
        setShowCounterModal(true);
      }
    } else {
      const defaultCounter = cashierCounters[0];
      if (defaultCounter) {
        setSelectedCounterId(defaultCounter.id);
        setSelectedCounter(defaultCounter.code);
        try {
          sessionStorage.setItem('pos_selected_counter_id', defaultCounter.id);
          sessionStorage.setItem('pos_selected_counter', defaultCounter.code);
          localStorage.setItem('pos_selected_counter_id', defaultCounter.id);
          localStorage.setItem('pos_selected_counter', defaultCounter.code);
        } catch { }
      }
      setShowCounterModal(true);
    }
  }, [activeBranch, selectedCounterId, selectedCounter, user?.role, currentBranchCode]);

