  const checkActiveShift = async () => {
    try {
      const res = await api<{ ok: boolean; activeShift: any }>('/api/shifts/active');
      if (res.activeShift) {
        setActiveShiftNumber(res.activeShift.shiftNumber || 'ACTIVE');
        if (user?.role === 'cashier' && res.activeShift.counter) {
          const shiftCounter = String(res.activeShift.counter).trim();
          const shiftCounterId = res.activeShift.counterId ? String(res.activeShift.counterId).trim() : '';
          const isRestricted = shiftCounter.toUpperCase().includes('ADMIN') || shiftCounter.toUpperCase().includes('MGR');
          if (!isRestricted) {
            setSelectedCounter(shiftCounter);
            if (shiftCounterId) setSelectedCounterId(shiftCounterId);
            try {
              sessionStorage.setItem('pos_selected_counter', shiftCounter);
              localStorage.setItem('pos_selected_counter', shiftCounter);
              if (shiftCounterId) {
                sessionStorage.setItem('pos_selected_counter_id', shiftCounterId);
                localStorage.setItem('pos_selected_counter_id', shiftCounterId);
              }
            } catch { }
          }
        }
      } else {
        setActiveShiftNumber(null);
      }
    } catch {
      setActiveShiftNumber(null);
    }
  };

  const loadItems = async () => {
    try {
      const res = await api<{ items: Item[] }>('/api/items?includeInactive=1');
      // Group products, keeping multi-branch products distinct so each branch's stock and identity are visible
      const raw = res.items || [];
      // Duplicate records of the same product (same SKU/barcode) can exist in one branch, e.g. when a
      // transfer was received under the source branch's item id. Show them as one card, but keep the
      // identity (id) of the record that actually holds the most stock in this branch, because the bill
      // is validated and deducted against that id only.
      const deduplicated: Item[] = [];
      const seen = new Map<string, { index: number; bestOwnStock: number; totalStock: number }>();
      for (const item of raw) {
        const branchKey = item.branchId || 'main';
        const skuKey = item.sku?.trim().toUpperCase();
        const barcodeKey = item.barcode?.trim();
        const key = `${branchKey}:${skuKey ? `sku:${skuKey}` : barcodeKey ? `bc:${barcodeKey}` : `id:${item.id}`}`;
        const ownStock = item.currentStockMilli || 0;
        const existing = seen.get(key);
        if (existing) {
          existing.totalStock += ownStock;
          if (ownStock > existing.bestOwnStock) {
            existing.bestOwnStock = ownStock;
            deduplicated[existing.index] = { ...item };
          }
          deduplicated[existing.index].currentStockMilli = existing.totalStock;
        } else {
          seen.set(key, { index: deduplicated.length, bestOwnStock: ownStock, totalStock: ownStock });
          deduplicated.push({ ...item });
        }
      }
      setItems(deduplicated);
    } catch (err) {
      console.error('Failed to load items', err);
    }
  };

  const loadCategories = async () => {
    try {
      const res = await api<{ categories: Category[] }>('/api/categories?includeInactive=1');
      const cats = res.categories || [];
      // Preserve distinct categories by unique ID so every category maintains independent status
      const uniqueCats: Category[] = [];
      const seenIds = new Set<string>();
      for (const c of cats) {
        if (c && c.id && !seenIds.has(c.id)) {
          seenIds.add(c.id);
          uniqueCats.push({
            ...c,
            active: Boolean(c.active),
          });
        }
      }
      setCategoriesList(uniqueCats);
      const activeCats = uniqueCats.filter((c) => c.active).map((c) => c.name);
      setCategories(activeCats);
    } catch (err) {
      console.error('Failed to load categories', err);
    }
  };

