  // Helper to determine available stock for an item in whole units for POS branch
  const getAvailableStockUnits = (itemId: string, fallbackItem?: Item): number => {
    if (!itemId || itemId.startsWith('custom-')) return Infinity;
    const catalogItem = items.find((it) => it.id === itemId) || fallbackItem;
    if (!catalogItem) return Infinity;
    const isTracked = (catalogItem as any).trackStock !== false && (catalogItem as any).track_stock !== false;
    if (!isTracked) return Infinity;
    const milli = Number(catalogItem.currentStockMilli ?? 0);
    if (milli <= 0) return 0;
    return Math.floor(milli / 1000);
  };

  // Cart operations with stock validation
  const addToCart = (item: Item, qtyToAdd: number = 1): boolean => {
    manuallyDecreasedItemsRef.current.delete(item.id);
    if (item.active === false || (item.trackStock !== false && (item.currentStockMilli ?? 0) <= 0)) {
      playAlertTone();
      showToast(`Cannot bill "${item.name}". Product is currently inactive or out of stock.`, 'warning');
      return false;
    }
    const avail = getAvailableStockUnits(item.id, item);
    if (avail <= 0) {
      playAlertTone();
      showToast(`Insufficient stock for "${item.name}". 0 units available.`, 'warning');
      return false;
    }

    const existing = cart.find((c) => c.item.id === item.id);
    const currentQty = existing ? existing.qty : 0;
    if (currentQty + qtyToAdd > avail) {
      playAlertTone();
      showToast(`Insufficient stock. Only ${avail} unit${avail === 1 ? '' : 's'} available.`, 'warning');
      return false;
    }

    setCart((prev) => {
      const found = prev.find((c) => c.item.id === item.id);
      if (found) {
        return prev.map((c) => (c.item.id === item.id ? { ...c, qty: c.qty + qtyToAdd } : c));
      }
      return [...prev, { item, qty: qtyToAdd }];
    });
    return true;
  };

  const updateCartQty = (itemId: string, delta: number) => {
    if (delta < 0) {
      manuallyDecreasedItemsRef.current.add(itemId);
    } else {
      manuallyDecreasedItemsRef.current.delete(itemId);
    }
    if (delta > 0) {
      const existing = cart.find((c) => c.item.id === itemId);
      if (existing?.isReturn) {
        showToast('Return item quantity cannot be increased beyond original returned amount.', 'warning');
        return;
      }
      const currentQty = existing ? existing.qty : 0;
      const avail = getAvailableStockUnits(itemId, existing?.item);
      if (currentQty + delta > avail) {
        playAlertTone();
        showToast(`Insufficient stock. Only ${avail} unit${avail === 1 ? '' : 's'} available.`, 'warning');
        return;
      }
    }
    setCart((prev) =>
      prev
        .map((c) => (c.item.id === itemId ? { ...c, qty: Math.max(0, c.qty + delta) } : c))
        .filter((c) => c.qty > 0)
    );
  };

  const updateCartQtyByIndex = (cartIdx: number, delta: number) => {
    setCart((prev) => {
      const target = prev[cartIdx];
      if (!target) return prev;
      if (delta > 0 && !target.isReturn) {
        const avail = target.variant?.stockMilli != null
          ? target.variant.stockMilli / 1000
          : getAvailableStockUnits(target.item.id, target.item);
        if (target.qty + delta > avail) {
          playAlertTone();
          showToast(`Insufficient stock. Only ${avail} unit${avail === 1 ? '' : 's'} available.`, 'warning');
          return prev;
        }
      }
      const newQty = target.qty + delta;
      if (newQty <= 0) {
        return prev.filter((_, idx) => idx !== cartIdx);
      }
      return prev.map((c, idx) => (idx === cartIdx ? { ...c, qty: newQty } : c));
    });
  };

  const handleDirectCartQtyChange = (cartIdx: number, val: number) => {
    setCart((prev) => {
      const target = prev[cartIdx];
      if (!target) return prev;
      if (val <= 0) {
        return prev.filter((_, idx) => idx !== cartIdx);
      }
      return prev.map((c, idx) => (idx === cartIdx ? { ...c, qty: val } : c));
    });
  };

  const toggleLengthUnit = (cartIdx: number) => {
    setCart((prev) => {
      const target = prev[cartIdx];
      if (!target) return prev;
      const curUnit = target.lengthUnit || (target.item.unit === 'yd' || target.item.unit === 'yard' ? 'yd' : 'm');
      if (curUnit === 'm') {
        const inYards = Number((target.qty / 0.9144).toFixed(3));
        return prev.map((c, idx) => (idx === cartIdx ? { ...c, qty: inYards, lengthUnit: 'yd' } : c));
      } else {
        const inMetres = Number((target.qty * 0.9144).toFixed(3));
        return prev.map((c, idx) => (idx === cartIdx ? { ...c, qty: inMetres, lengthUnit: 'm' } : c));
      }
    });
  };

  const handleSelectVariantFromPicker = (variant: ProductVariant) => {
    if (!variantPickerItem) return;
    setCart((prev) => {
      const foundIdx = prev.findIndex((c) => c.item.id === variantPickerItem.id && c.variant?.id === variant.id);
      if (foundIdx >= 0) {
        return prev.map((c, idx) =>
          idx === foundIdx ? { ...c, qty: c.qty + 1 } : c
        );
      }
      const variantItem: Item = {
        ...variantPickerItem,
        priceMinor: variant.priceMinor,
        mrpMinor: variant.mrpMinor ?? variantPickerItem.mrpMinor,
        currentStockMilli: variant.stockMilli ?? variantPickerItem.currentStockMilli,
        sku: variant.sku || variantPickerItem.sku,
        barcode: variant.barcode || variantPickerItem.barcode,
      };
      return [...prev, { item: variantItem, qty: 1, variant }];
    });
    playSupermarketBeep();
    showToast(`Added ${variantPickerItem.name} (${variant.size || ''} / ${variant.colour || ''})`);
  };

  const handleExchangeVariant = (oldVariantId: string | null, newVariant: ProductVariant) => {
    if (!variantPickerItem) return;
    setCart((prev) =>
      prev.map((c) => {
        if (c.item.id === variantPickerItem.id && (oldVariantId ? c.variant?.id === oldVariantId : true)) {
          const updatedItem: Item = {
            ...c.item,
            priceMinor: newVariant.priceMinor,
            mrpMinor: newVariant.mrpMinor ?? c.item.mrpMinor,
            currentStockMilli: newVariant.stockMilli ?? c.item.currentStockMilli,
            sku: newVariant.sku || c.item.sku,
            barcode: newVariant.barcode || c.item.barcode,
          };
          return {
            ...c,
            item: updatedItem,
            variant: newVariant,
          };
        }
        return c;
      })
    );
    showToast(`Exchanged to ${newVariant.size || ''} / ${newVariant.colour || ''}`);
  };

  const addCuttingCharge = () => {
    const chargeStr = prompt('Enter Tailoring / Cutting / Stitching charge amount (₹):', '50');
    if (!chargeStr) return;
    const val = parseFloat(chargeStr);
    if (isNaN(val) || val <= 0) return;
    const chargeItem: Item = {
      id: `charge_${Date.now()}`,
      name: 'Tailoring / Cutting Charge (SAC 9988)',
      priceMinor: Math.round(val * 100),
      unit: 'svc',
      currentStockMilli: 999000,
      active: true,
      hsn: '9988',
      taxRateBp: Boolean(shop?.gstEnabled) ? 500 : 0,
    } as Item;
    setCart((prev) => [...prev, { item: chargeItem, qty: 1, lineType: 'cutting_charge' }]);
    showToast(`Added Tailoring Charge of ₹${val.toFixed(2)}`);
  };

  const handleAddRatioLinesToPurchase = (lines: any[]) => {
    setPurLines((prev) => [
      ...prev,
      ...lines.map((l) => ({
        itemId: l.itemId,
        name: l.name,
        billedQty: l.billedQtyMilli / 1000,
        receivedQty: l.receivedQtyMilli / 1000,
        costRupees: l.costMinor / 100,
        taxRateBp: l.taxRateBp || 0,
        unit: l.unit || 'pcs',
        discountRupees: 0,
        batchNo: '',
        expiry: '',
        variantId: l.variantId || null,
      })),
    ]);
    showToast(`Added ${lines.length} inward line(s) to purchase`);
  };

  // Play authentic POS supermarket checkout beep tone
  const playSupermarketBeep = () => {
    if (!scannerSoundEnabled) return;
    try {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      if (!AudioCtx) return;
      const ctx = new AudioCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(1760, ctx.currentTime);
      gain.gain.setValueAtTime(0.22, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.09);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.1);
    } catch { }
  };

  const playAlertTone = () => {
    if (!scannerSoundEnabled) return;
    try {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      if (!AudioCtx) return;
      const ctx = new AudioCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(320, ctx.currentTime);
      gain.gain.setValueAtTime(0.18, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.18);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.19);
    } catch { }
  };

  // Desktop debounce to prevent duplicate burst scans
  const lastDesktopScanTimeRef = useRef<{ [code: string]: number }>({});
  const processedScanIdsRef = useRef(new Set<string>());
  const itemsRef = useRef(items);
  useEffect(() => {
    itemsRef.current = items;
  }, [items]);

  // Barcode scanned from phone or physical USB barcode gun
  const handleBarcodeScanned = async (barcode: string) => {
    const rawClean = (barcode || '').trim();
    if (!rawClean) return;

    // 0. If POS Return & Exchange Modal is currently open, forward scan directly to it
    if (showReturnExchangeModalRef.current) {
      setExternalBarcodeScan({ barcode: rawClean, timestamp: Date.now() });
      return;
    }

    // 0b. If barcode matches an invoice or credit note pattern (e.g. WH-1005, INV-1001, CN-1001), auto-launch Return & Exchange
    if (/^(WH-|INV-|CN-)/i.test(rawClean)) {
      setShowReturnExchangeModal(true);
      setExternalBarcodeScan({ barcode: rawClean, timestamp: Date.now() });
      showToast(`Opening Return & Exchange for ${rawClean}...`);
      return;
    }

    const clean = rawClean.replace(/[\s\-]/g, '');
    if (!clean) return;

    // Desktop debounce: prevent duplicate scan of the same barcode within 2.2 seconds
    const now = Date.now();
    if (lastDesktopScanTimeRef.current[clean] && now - lastDesktopScanTimeRef.current[clean] < 2200) {
      return;
    }
    lastDesktopScanTimeRef.current[clean] = now;

    // 1. Match item in memory by exact barcode, stripped barcode, no-leading-zero barcode, 12 vs 13-digit EAN, prefix/suffix, or SKU
    const cleanNoZero = clean.replace(/^0+/, '');
    const catalog = itemsRef.current.length > 0 ? itemsRef.current : items;
    let matched = catalog.find((it) => {
      if (!it) return false;
      const itBc = (it.barcode || '').trim().replace(/[\s\-]/g, '');
      const itBcNoZero = itBc.replace(/^0+/, '');
      if (itBc) {
        if (itBc === clean) return true;
        if (itBcNoZero === cleanNoZero) return true;
        // Known camera glare/screen moiré readings for Aashirvaad Atta (from screen scans):
        if ((clean === '8901134467801' || clean === '3612360567801') && (itBc.includes('67801') || itBc.includes('567801') || it.name.toLowerCase().includes('aashirvaad'))) return true;
        // 12-digit vs 13-digit EAN-13 check digit equivalence (e.g. 890172518123 vs 8901725181239)
        if (clean.length === 13 && itBc.length === 12 && clean.startsWith(itBc)) return true;
        if (clean.length === 12 && itBc.length === 13 && itBc.startsWith(clean)) return true;
        // 13-digit with recomputed check digit (e.g. 8901234567801 vs 8901234567807)
        if (clean.length === 13 && itBc.length === 13 && clean.slice(0, 12) === itBc.slice(0, 12)) return true;
        // Suffix match: if last 5 digits match (unique item code suffix within retail store)
        if (clean.length >= 8 && itBc.length >= 8 && clean.slice(-5) === itBc.slice(-5)) return true;
        // Prefix match for barcodes >= 8 digits
        if (clean.length >= 8 && itBc.length >= 8 && (itBc.startsWith(clean) || clean.startsWith(itBc))) return true;
      }
      if (it.sku && it.sku.trim().toLowerCase() === clean.toLowerCase()) return true;
      return false;
    });

    // 1b. Robust optical noise tolerance: If camera reflection/screen moiré distorted up to 3 digits:
    if (!matched && clean.length >= 8 && /^\d+$/.test(clean)) {
      let bestItem: Item | null = null;
      let minDiffs = 999;
      for (const it of catalog) {
        if (!it?.barcode) continue;
        const itBc = it.barcode.trim().replace(/[\s\-]/g, '');
        if (Math.abs(itBc.length - clean.length) > 1) continue;
        let diffs = 0;
        const minLen = Math.min(clean.length, itBc.length);
        for (let i = 0; i < minLen; i++) {
          if (clean[i] !== itBc[i]) diffs++;
        }
        diffs += Math.abs(clean.length - itBc.length);
        if (diffs <= 3 && diffs < minDiffs) {
          minDiffs = diffs;
          bestItem = it;
        }
      }
      if (bestItem && minDiffs <= 3) {
        matched = bestItem;
        console.log(`[Optical Repair] Scanned ${clean} auto-matched ${matched.name} (${matched.barcode}) with ${minDiffs} digits repaired.`);
      }
    }

    // 2. If not found in primary barcode, query backend by-barcode endpoint (which checks product_barcodes table!)
    if (!matched) {
      try {
        const res = await api<{ item: Item }>(`/api/items/by-barcode/${encodeURIComponent(clean)}`);
        if (res?.item) {
          matched = res.item;
        }
      } catch { }
    }

    // 2b. If still not found, check variants lookup endpoint
    if (!matched) {
      try {
        const vRes = await api<{ matches?: Array<{ id: string; product_id: string; size: string; colour: string; price_minor: number; mrp_minor?: number; stock_milli: number; sku: string; barcode: string; product_name: string }> }>(`/api/variants/lookup?q=${encodeURIComponent(clean)}`);
        if (vRes?.matches && vRes.matches.length > 0) {
          const match = vRes.matches[0];
          const parentItem = catalog.find((it) => it.id === match.product_id);
          if (parentItem) {
            setActiveTab('pos');
            const varObj: ProductVariant = {
              id: match.id,
              tenantId: '',
              productId: match.product_id,
              size: match.size,
              colour: match.colour,
              sku: match.sku,
              barcode: match.barcode,
              costMinor: (match as any).cost_minor ?? parentItem.costMinor ?? 0,
              priceMinor: match.price_minor,
              mrpMinor: match.mrp_minor,
              stockMilli: match.stock_milli,
              active: true,
            };
            handleSelectVariantFromPicker(varObj);
            return;
          }
        }
      } catch { }
    }

    console.log('📱 Barcode received on desktop:', clean, 'Matched item:', matched?.name);

    if (matched) {
      if (matched.active === false || (matched.trackStock !== false && (matched.currentStockMilli ?? 0) <= 0)) {
        playAlertTone();
        showToast(`⚠️ "${matched.name}" is inactive / out of stock and cannot be billed.`, 'warning');
        return;
      }
      // Automatically switch to POS Billing tab if user is currently on another tab (like Products catalog)!
      setActiveTab('pos');

      if (matched.itemType === 'variant') {
        setVariantPickerItem(matched);
        setVariantPickerCurrentVarId(null);
        setVariantPickerMode('add_to_cart');
        setIsVariantPickerOpen(true);
        return;
      }

      const added = addToCart(matched);
      if (added) {
        playSupermarketBeep();
        showToast(`🛒 Scanned: ${matched.name} (+1 in cart)`);
      }
    } else {
      playAlertTone();
      showToast(`⚠️ Barcode "${rawClean}" not found in catalog`);
    }
  };

  // ── Inline POS Camera Scanner Handlers ──
  const handleInlineCameraScan = useCallback((decodedText: string) => {
    const rawClean = (decodedText || '').trim();
    if (!rawClean) return;

    const now = Date.now();
    if (lastCameraScanRef.current && lastCameraScanRef.current.code === rawClean && now - lastCameraScanRef.current.time < 2000) {
      return;
    }
    lastCameraScanRef.current = { code: rawClean, time: now };

    setCameraScanFlash(true);
    setTimeout(() => setCameraScanFlash(false), 350);

    handleBarcodeScanned(rawClean);
  }, []);

  const stopPosCamera = useCallback(async () => {
    isPosCameraStartingRef.current = false;
    setIsPosCameraStarting(false);
    if (posHtml5QrCodeRef.current) {
      try {
        const scanner = posHtml5QrCodeRef.current;
        posHtml5QrCodeRef.current = null;
        if (scanner.isScanning) {
          await scanner.stop();
        }
        scanner.clear();
      } catch {
        // ignore errors on stopping
      }
    }
    setIsPosCameraActive(false);
    setPosCameraError(null);
  }, []);

  const startPosCamera = useCallback(async (cameraIdToUse?: string) => {
    if (isPosCameraStartingRef.current) return;
    isPosCameraStartingRef.current = true;
    setIsPosCameraStarting(true);
    setPosCameraError(null);

    try {
      const isSecure = typeof window !== 'undefined' && (
        Boolean(window.isSecureContext) ||
        window.location.hostname === 'localhost' ||
        window.location.hostname === '127.0.0.1'
      );
      if (!isSecure) {
        setPosCameraError('Live camera requires HTTPS or localhost in your browser.');
        setIsPosCameraStarting(false);
        isPosCameraStartingRef.current = false;
        return;
      }

      let devices: Array<{ id: string; label: string }> = [];
      try {
        devices = await Html5Qrcode.getCameras();
      } catch (camErr: any) {
        console.warn('Could not enumerate cameras:', camErr);
        devices = [];
      }

      if (!devices || devices.length === 0) {
        setPosCameraError('No camera found or permission denied. Please connect a webcam.');
        setIsPosCameraStarting(false);
        isPosCameraStartingRef.current = false;
        return;
      }

      setPosCameraDevices(devices.map((d) => ({ id: d.id, label: d.label || `Camera ${d.id.slice(0, 5)}` })));

      const chosenId = cameraIdToUse || selectedPosCameraId || (() => {
        const back = devices.find((d) => /back|rear|environment|external|webcam/i.test(d.label));
        return back ? back.id : devices[0].id;
      })();
      setSelectedPosCameraId(chosenId);

      // Stop existing if any
      if (posHtml5QrCodeRef.current) {
        try {
          if (posHtml5QrCodeRef.current.isScanning) {
            await posHtml5QrCodeRef.current.stop();
          }
          posHtml5QrCodeRef.current.clear();
        } catch { }
        posHtml5QrCodeRef.current = null;
      }

      setIsPosCameraActive(true);

      // Allow container to mount in DOM
      setTimeout(async () => {
        const container = document.getElementById('pos-inline-camera-view');
        if (!container) {
          setIsPosCameraStarting(false);
          isPosCameraStartingRef.current = false;
          return;
        }

        try {
          const qrScanner = new Html5Qrcode('pos-inline-camera-view', {
            formatsToSupport: [
              Html5QrcodeSupportedFormats.EAN_13,
              Html5QrcodeSupportedFormats.EAN_8,
              Html5QrcodeSupportedFormats.UPC_A,
              Html5QrcodeSupportedFormats.UPC_E,
              Html5QrcodeSupportedFormats.CODE_128,
              Html5QrcodeSupportedFormats.CODE_39,
              Html5QrcodeSupportedFormats.QR_CODE,
            ],
            verbose: false,
          });
          posHtml5QrCodeRef.current = qrScanner;

          await qrScanner.start(
            chosenId,
            {
              fps: 16,
              qrbox: (viewfinderWidth, viewfinderHeight) => {
                const w = Math.max(50, Math.min(280, Math.floor((viewfinderWidth || 280) * 0.88)));
                const h = Math.max(50, Math.min(160, Math.floor((viewfinderHeight || 160) * 0.65)));
                return { width: w, height: h };
              },
              aspectRatio: 1.777,
            },
            (decodedText) => {
              handleInlineCameraScan(decodedText);
            },
            () => { }
          );

          // Force dimensions on html5-qrcode generated elements to prevent vertical stretching
          const vEl = document.getElementById('pos-inline-camera-view');
          if (vEl) {
            vEl.style.width = '100%';
            vEl.style.height = '100%';
            vEl.style.maxHeight = '100%';
            const vid = vEl.querySelector('video');
            if (vid) {
              vid.style.width = '100%';
              vid.style.height = '100%';
              vid.style.maxHeight = '100%';
              vid.style.objectFit = 'cover';
            }
          }

          setIsPosCameraStarting(false);
          isPosCameraStartingRef.current = false;
        } catch (err: any) {
          try {
            if (posHtml5QrCodeRef.current) {
              posHtml5QrCodeRef.current.clear();
              posHtml5QrCodeRef.current = null;
            }
          } catch { }
          setPosCameraError(err?.message || 'Could not start camera stream.');
          setIsPosCameraStarting(false);
          isPosCameraStartingRef.current = false;
        }
      }, 120);
    } catch (err: any) {
      setPosCameraError(err?.message || 'Camera permission denied or camera not accessible.');
      setIsPosCameraStarting(false);
      isPosCameraStartingRef.current = false;
    }
  }, [selectedPosCameraId, handleInlineCameraScan]);

  const switchPosCamera = useCallback(async () => {
    if (posCameraDevices.length < 2) return;
    const currentIndex = posCameraDevices.findIndex((d) => d.id === selectedPosCameraId);
    const nextIndex = (currentIndex + 1) % posCameraDevices.length;
    const nextCamera = posCameraDevices[nextIndex];
    if (nextCamera) {
      setSelectedPosCameraId(nextCamera.id);
      await stopPosCamera();
      startPosCamera(nextCamera.id);
    }
  }, [posCameraDevices, selectedPosCameraId, stopPosCamera, startPosCamera]);

  // Clean up camera on tab switch away from POS or on unmount
  useEffect(() => {
    if (activeTab !== 'pos' && isPosCameraActive) {
      stopPosCamera();
    }
  }, [activeTab, isPosCameraActive, stopPosCamera]);

  useEffect(() => {
    return () => {
      if (posHtml5QrCodeRef.current) {
        try {
          if (posHtml5QrCodeRef.current.isScanning) {
            posHtml5QrCodeRef.current.stop().catch(() => { });
          }
          posHtml5QrCodeRef.current.clear();
        } catch { }
        posHtml5QrCodeRef.current = null;
      }
    };
  }, []);

  // Fetch local LAN network info when opening mobile scanner modal or return & exchange modal
  useEffect(() => {
    if (!showMobileScannerModal && !showReturnExchangeModal) return;

    const fetchInfo = () => {
      fetch('/api/scanner/network-info')
        .then((r) => r.json())
        .then((data) => {
          setScannerNetworkInfo(data);
          // Intelligently select best initial protocol if not custom
          setScannerProtocol((prev) => {
            if (customTunnelUrl) return 'tunnel';
            const isLive = typeof window !== 'undefined' && window.location.hostname !== 'localhost' && window.location.hostname !== '127.0.0.1';
            if (isLive) return 'server';
            if (data?.tunnelUrl) return 'tunnel';
            if (data?.isLanAvailable || data?.lanIp) return 'wifi';
            return prev || 'wifi';
          });
        })
        .catch(() => { });
    };

    fetchInfo();
    const timer = setInterval(fetchInfo, 3000);
    return () => clearInterval(timer);
  }, [showMobileScannerModal, showReturnExchangeModal, customTunnelUrl]);

  // Real-time listener: receives barcodes scanned from mobile phone instantly
  useEffect(() => {
    let active = true;
    let lastScanId = '';
    let consecutiveErrors = 0;

    const listenForScans = async () => {
      while (active) {
        try {
          const url = `/api/scanner/events?session=${encodeURIComponent(scannerSessionId)}${lastScanId ? `&after=${encodeURIComponent(lastScanId)}` : ''}`;
          const res = await fetch(url);
          if (!res.ok) {
            consecutiveErrors++;
            if (consecutiveErrors >= 3) {
              setScannerStatus('unable_to_connect');
            }
            await new Promise((r) => setTimeout(r, 2000));
            continue;
          }
          consecutiveErrors = 0;
          const data = await res.json();
          if (!active) break;

          if (data.status) {
            setScannerStatus(data.status);
          } else if (data.phoneConnected !== undefined) {
            setScannerStatus(data.phoneConnected ? (data.cameraReady ? 'scanner_ready' : 'phone_connected') : 'waiting');
          }
          if (data.phoneConnected !== undefined) {
            setIsPhoneScannerConnected(Boolean(data.phoneConnected));
          }

          if (data.events && Array.isArray(data.events) && data.events.length > 0) {
            for (const ev of data.events) {
              lastScanId = ev.id;
              if (processedScanIdsRef.current.has(ev.id)) continue;
              processedScanIdsRef.current.add(ev.id);
              if (showReturnExchangeModalRef.current) {
                setExternalBarcodeScan({ barcode: ev.barcode, timestamp: Date.now() });
              } else {
                await handleBarcodeScanned(ev.barcode);
              }
            }
          }
        } catch {
          if (active) {
            consecutiveErrors++;
            if (consecutiveErrors >= 3) {
              setScannerStatus('unable_to_connect');
            }
            await new Promise((r) => setTimeout(r, 2500));
          }
        }
      }
    };

    listenForScans();
    return () => {
      active = false;
    };
  }, [scannerSessionId]);

  // Customer & Loyalty Points for Active Selected Customer
  const selectedParty = parties.find((p) => p.id === selectedPartyId);

  const getPartyLoyaltyPoints = (partyId?: string, partyPhone?: string) => {
    if (!partyId && !partyPhone) return 0;
    const party = parties.find((p) => (partyId && p.id === partyId) || (partyPhone && p.phone === partyPhone));
    return party?.loyaltyPoints ?? 0;
  };

  const selectedPartyPoints = useMemo(() => {
    if (!selectedParty) return 0;
    return selectedParty.loyaltyPoints ?? 0;
  }, [selectedParty]);

  // Cart items separated into normal purchase items and return items
  const normalCartItems = useMemo(() => cart.filter((c) => !c.isReturn), [cart]);
  const returnCartItems = useMemo(() => cart.filter((c) => c.isReturn), [cart]);
  const isExchangeActive = activeExchangeLines.length > 0 || returnCartItems.length > 0;

  // Total Exchange Return Credit available from returned goods
  const totalExchangeCreditMinor = useMemo(() => {
    const fromCart = returnCartItems.reduce((acc, c) => acc + Math.abs(c.item.priceMinor) * c.qty, 0);
    const fromLines = activeExchangeLines.reduce((acc, l) => acc + (l.estimatedCreditMinor || 0), 0);
    return Math.max(fromCart, fromLines);
  }, [returnCartItems, activeExchangeLines]);

  // New Items Base (Taxable), Taxes & Subtotal (for exchange or normal sale)
  const newItemsTaxableMinor = useMemo(() => {
    return normalCartItems.reduce((acc, c) => acc + c.item.priceMinor * c.qty, 0);
  }, [normalCartItems]);

  const newItemsTaxMinor = useMemo(() => {
    return normalCartItems.reduce((acc, c) => {
      const taxable = c.item.priceMinor * c.qty;
      const tax = Math.round((taxable * (c.item.taxRateBp || 0)) / 10000);
      return acc + tax;
    }, 0);
  }, [normalCartItems]);

  const newItemsSubtotalMinor = newItemsTaxableMinor + newItemsTaxMinor;
  const newItemsCgstMinor = Math.floor(newItemsTaxMinor / 2);
  const newItemsSgstMinor = newItemsTaxMinor - newItemsCgstMinor;

  // Cart Taxable & Taxes for General POS or Exchange
  const cartTaxableMinor = isExchangeActive
    ? newItemsTaxableMinor
    : cart.reduce((acc, c) => acc + c.item.priceMinor * c.qty, 0);

  const cartTaxMinor = isExchangeActive
    ? newItemsTaxMinor
    : cart.reduce((acc, c) => {
      const taxable = c.item.priceMinor * c.qty;
      const tax = Math.round((taxable * (c.item.taxRateBp || 0)) / 10000);
      return acc + tax;
    }, 0);

  const cartCgstMinor = isExchangeActive ? newItemsCgstMinor : Math.floor(cartTaxMinor / 2);
  const cartSgstMinor = isExchangeActive ? newItemsSgstMinor : cartTaxMinor - cartCgstMinor;
  const cartSubtotalMinor = cartTaxableMinor + cartTaxMinor;
  const cartTotalMinor = cartSubtotalMinor;
  const percentDiscountMinor = Math.round((cartTotalMinor * appliedDiscountPercent) / 100);
  const maxPointsDiscountMinor = Math.max(0, cartTotalMinor - percentDiscountMinor);
  // Custom Shop Loyalty Scheme Calculations
  const shopPointValMinor = shop?.loyaltyPointValueMinor ?? 10;
  const shopMinRedeem = shop?.loyaltyMinPointsRedeem ?? 10;
  const shopPointsPer100 = shop?.loyaltyPointsPer100 ?? 10;
  const shopLoyaltyActive = shop?.loyaltyEnabled !== false;

  const potentialDiscountMinor = (selectedPartyPoints >= shopMinRedeem && shopLoyaltyActive)
    ? Math.min(maxPointsDiscountMinor, selectedPartyPoints * shopPointValMinor)
    : 0;
  const maxRedeemablePoints = shopPointValMinor > 0 ? Math.ceil(potentialDiscountMinor / shopPointValMinor) : 0;
  const pointsDiscountMinor = redeemPoints ? potentialDiscountMinor : 0;
  const pointsActuallyRedeemed = redeemPoints ? maxRedeemablePoints : 0;
  const promoDiscountMinor = promoEvalResult?.totalDiscountMinor || 0;
  const cartOfferDiscountMinor = useMemo(() => {
    return normalCartItems.reduce((acc, c) => {
      if (c.item.offerPercentage && c.item.offerPercentage > 0) {
        return acc + Math.round((c.item.priceMinor * c.item.offerPercentage) / 100) * c.qty;
      }
      return acc;
    }, 0);
  }, [normalCartItems]);
  const discountMinor = cartOfferDiscountMinor + percentDiscountMinor + pointsDiscountMinor + promoDiscountMinor;

  // Amount payable on new items after discounts
  const newItemsPayableMinor = Math.max(0, cartTotalMinor - discountMinor);

  // Net Exchange Balance Math:
  // If customer buys more than return credit -> customer pays the positive difference
  // If return credit is more than new purchase -> shop owes customer a refund
  const exchangeCustomerPayableMinor = isExchangeActive
    ? Math.max(0, newItemsPayableMinor - totalExchangeCreditMinor)
    : 0;

  const exchangeCustomerRefundMinor = isExchangeActive
    ? Math.max(0, totalExchangeCreditMinor - newItemsPayableMinor)
    : 0;

  // Final amount to tender / collect at POS terminal
  const finalPayableMinor = isExchangeActive
    ? exchangeCustomerPayableMinor
    : Math.max(0, cartTotalMinor - discountMinor);

  // Net Loyalty Points on Exchange / Bill:
  const netLoyaltyPointsToEarn = useMemo(() => {
    if (!shopLoyaltyActive || shopPointsPer100 <= 0) return 0;
    if (isExchangeActive) {
      const earnedOnNew = Math.floor((newItemsPayableMinor * shopPointsPer100) / 10000);
      const reversedOnReturn = Math.floor((totalExchangeCreditMinor * shopPointsPer100) / 10000);
      return earnedOnNew - reversedOnReturn;
    }
    return Math.floor((finalPayableMinor * shopPointsPer100) / 10000);
  }, [shopLoyaltyActive, shopPointsPer100, isExchangeActive, newItemsPayableMinor, totalExchangeCreditMinor, finalPayableMinor]);

  const pointsToEarnOnBill = Math.max(0, netLoyaltyPointsToEarn);

  // Cash Tender & Change Return calculation
  const cashReceivedValMinor = cashReceived.trim() !== ''
    ? Math.round(parseFloat(cashReceived) * 100) || 0
    : finalPayableMinor;
  const changeDueMinor = Math.max(0, cashReceivedValMinor - finalPayableMinor);
  const remainingDueMinor = Math.max(0, finalPayableMinor - cashReceivedValMinor);

  const suggestedDenominations = useMemo(() => {
    const base = Math.ceil(finalPayableMinor / 100);
    if (base <= 0) return [100, 200, 500, 2000];
    const s = new Set<number>();
    s.add(base);
    if (base % 50 !== 0 && base < 500) s.add(Math.ceil(base / 50) * 50);
    if (base % 100 !== 0 && base < 1000) s.add(Math.ceil(base / 100) * 100);
    if (base < 500) s.add(500);
    if (base < 1000) s.add(1000);
    if (base < 2000) s.add(2000);
    return Array.from(s).sort((a, b) => a - b).slice(0, 5);
  }, [finalPayableMinor]);

  // Split Payment (Multi-Tender) Calculations
  const split1Minor = splitAmount1.trim() !== '' ? Math.round(parseFloat(splitAmount1) * 100) || 0 : 0;
  const split2Minor = splitAmount2.trim() !== '' ? Math.round(parseFloat(splitAmount2) * 100) || 0 : 0;
  const splitTotalMinor = split1Minor + split2Minor;
  const splitRemainingMinor = Math.max(0, finalPayableMinor - splitTotalMinor);
  const splitOverMinor = Math.max(0, splitTotalMinor - finalPayableMinor);

  const hasCashInSplit = splitMethod1 === 'cash' || splitMethod2 === 'cash';
  const splitAllocatedCashMinor = splitMethod1 === 'cash' ? split1Minor : (splitMethod2 === 'cash' ? split2Minor : 0);
  const splitCashGivenMinor = splitCashTendered.trim() !== ''
    ? Math.round(parseFloat(splitCashTendered) * 100) || 0
    : splitAllocatedCashMinor;
  const splitCashChangeMinor = Math.max(0, splitCashGivenMinor - splitAllocatedCashMinor);
  const splitCashShortMinor = Math.max(0, splitAllocatedCashMinor - splitCashGivenMinor);

  const handleSplitFiftyFifty = () => {
    const totalRupees = +(finalPayableMinor / 100).toFixed(2);
    const half1 = +(totalRupees / 2).toFixed(2);
    const half2 = +(totalRupees - half1).toFixed(2);
    setSplitMethod1('cash');
    setSplitMethod2('upi');
    setSplitAmount1(half1.toString());
    setSplitAmount2(half2.toString());
    setSplitCashTendered('');
  };

  const handleSplit1Change = (val: string) => {
    lastSplitEditedRef.current = 1;
    setSplitAmount1(val);
    if (val.trim() === '') {
      setSplitAmount2('');
      return;
    }
    const num = parseFloat(val);
    if (!isNaN(num)) {
      const totalRupees = finalPayableMinor / 100;
      const remaining = Math.max(0, +(totalRupees - num).toFixed(2));
      setSplitAmount2(remaining.toString());
    }
  };

  const handleSplit2Change = (val: string) => {
    lastSplitEditedRef.current = 2;
    setSplitAmount2(val);
    if (val.trim() === '') {
      setSplitAmount1('');
      return;
    }
    const num = parseFloat(val);
    if (!isNaN(num)) {
      const totalRupees = finalPayableMinor / 100;
      const remaining = Math.max(0, +(totalRupees - num).toFixed(2));
      setSplitAmount1(remaining.toString());
    }
  };

  // Keep split balance automatically updated whenever total or mode changes
  useEffect(() => {
    if (selectedPayMode === 'split' && cart.length > 0) {
      const totalRupees = finalPayableMinor / 100;
      if (!splitAmount1 && !splitAmount2) {
        handleSplitFiftyFifty();
        return;
      }
      if (lastSplitEditedRef.current === 1 && splitAmount1.trim() !== '') {
        const num1 = parseFloat(splitAmount1);
        if (!isNaN(num1)) {
          const rem = Math.max(0, +(totalRupees - num1).toFixed(2));
          setSplitAmount2(rem.toString());
        }
      } else if (lastSplitEditedRef.current === 2 && splitAmount2.trim() !== '') {
        const num2 = parseFloat(splitAmount2);
        if (!isNaN(num2)) {
          const rem = Math.max(0, +(totalRupees - num2).toFixed(2));
          setSplitAmount1(rem.toString());
        }
      }
    }
  }, [finalPayableMinor, selectedPayMode, cart.length]);

  const handleFillSplitRemaining = (targetField: 1 | 2) => {
    const totalRupees = finalPayableMinor / 100;
    if (targetField === 1) {
      const amt2 = parseFloat(splitAmount2) || 0;
      setSplitAmount1(Math.max(0, +(totalRupees - amt2).toFixed(2)).toString());
    } else {
      const amt1 = parseFloat(splitAmount1) || 0;
      setSplitAmount2(Math.max(0, +(totalRupees - amt1).toFixed(2)).toString());
    }
  };

  // Cart MRP, Savings, and Category Breakdown
  const cartTotalMrpMinor = cart.reduce((acc, c) => acc + (c.isReturn ? 0 : getItemMrp(c.item) * c.qty), 0);
  const totalMrpSavingsMinor = Math.max(0, cartTotalMrpMinor - Math.max(0, cartSubtotalMinor)) + discountMinor;
  const cartCategoryBreakdown = cart.reduce((acc: { [cat: string]: { name: string; count: number; totalMinor: number } }, c) => {
    if (c.isReturn) return acc;
    const cat = c.item.category?.trim() || 'General';
    if (!acc[cat]) {
      acc[cat] = { name: cat, count: 0, totalMinor: 0 };
    }
    acc[cat].count += c.qty;
    acc[cat].totalMinor += c.item.priceMinor * c.qty;
    return acc;
  }, {});

  // Real-time Customer-Facing Display (CFD) Synchronization
  useEffect(() => {
    const counterId = 'counter-1';
    let bChannel: BroadcastChannel | null = null;
    try {
      bChannel = new BroadcastChannel(`cfd_${counterId}`);
    } catch { }

    const isUpiInSplit1 = splitMethod1 === 'upi';
    const isUpiInSplit2 = splitMethod2 === 'upi';
    const hasUpiInSplit = isUpiInSplit1 || isUpiInSplit2;

    let splitUpiMinor = 0;
    if (hasUpiInSplit) {
      if (isUpiInSplit1 && isUpiInSplit2) {
        splitUpiMinor = (split1Minor + split2Minor) > 0 ? (split1Minor + split2Minor) : finalPayableMinor;
      } else if (isUpiInSplit1) {
        splitUpiMinor = split1Minor > 0 ? split1Minor : (split2Minor > 0 ? Math.max(0, finalPayableMinor - split2Minor) : finalPayableMinor);
      } else {
        splitUpiMinor = split2Minor > 0 ? split2Minor : (split1Minor > 0 ? Math.max(0, finalPayableMinor - split1Minor) : finalPayableMinor);
      }
    }

    const otherSplitMethod = isUpiInSplit1 ? splitMethod2 : (isUpiInSplit2 ? splitMethod1 : undefined);
    const otherSplitMinor = isUpiInSplit1
      ? (split2Minor > 0 ? split2Minor : Math.max(0, finalPayableMinor - splitUpiMinor))
      : (split1Minor > 0 ? split1Minor : Math.max(0, finalPayableMinor - splitUpiMinor));

    // Determine status
    let status: 'idle' | 'billing' | 'payment_upi' | 'payment_cash' | 'payment_card' | 'payment_bank' | 'payment_split' | 'completed' = 'idle';
    if (checkoutSuccess) {
      status = 'completed';
    } else if (cart.length > 0) {
      if (selectedPayMode === 'upi') status = 'payment_upi';
      else if (selectedPayMode === 'split') status = hasUpiInSplit ? 'payment_upi' : 'payment_split';
      else if (selectedPayMode === 'cash') status = 'payment_cash';
      else if (selectedPayMode === 'card') status = 'payment_card';
      else if (selectedPayMode === 'bank') status = 'payment_bank';
      else status = 'billing';
    }

    const effectivePayableUpiMinor = (selectedPayMode === 'split' && hasUpiInSplit) ? splitUpiMinor : finalPayableMinor;
    const effectiveUpiId = shop?.upiId?.trim() || (shop?.phone ? `${shop.phone.replace(/\D/g, '').slice(-10)}@upi` : 'merchant@okaxis');
    const upiUrl = effectivePayableUpiMinor > 0
      ? `upi://pay?pa=${encodeURIComponent(effectiveUpiId)}&pn=${encodeURIComponent(shop?.name || 'Store')}&am=${(effectivePayableUpiMinor / 100).toFixed(2)}&cu=INR&tn=${encodeURIComponent(`${selectedPayMode === 'split' ? 'Split payment' : 'Bill'} at ${shop?.name || 'Store'}`)}`
      : undefined;

    const activeCustomer = parties.find((p) => p.id === selectedPartyId);
    const payload = {
      counterId,
      shopName: shop?.name || 'Retail POS Counter',
      upiId: effectiveUpiId,
      tagline: shop?.address ? `Store: ${shop.address}` : 'GST Registered Retail Billing',
      cashierName: user?.name || 'Register Cashier',
      customerName: activeCustomer?.name || (cart.length > 0 ? 'Standard Retail Customer' : ''),
      items: cart.map((c) => {
        const mrp = getItemMrp(c.item);
        const storePrice = c.item.priceMinor;
        const lineTotal = storePrice * c.qty;
        const lineSavings = Math.max(0, (mrp - storePrice) * c.qty);
        return {
          id: c.item.id,
          name: c.item.name,
          sku: c.item.sku,
          qty: c.qty,
          unit: c.item.unit || 'pcs',
          category: c.item.category?.trim() || 'General',
          mrpMinor: mrp,
          priceMinor: storePrice,
          totalMinor: lineTotal,
          savingsMinor: lineSavings,
        };
      }),
      categoryBreakdown: cartCategoryBreakdown,
      itemCount: cart.length,
      totalUnits: cart.reduce((sum, c) => sum + c.qty, 0),
      totalMrpMinor: cartTotalMrpMinor,
      taxableSubtotalMinor: cartTaxableMinor,
      cgstMinor: cartCgstMinor,
      sgstMinor: cartSgstMinor,
      subtotalMinor: cartSubtotalMinor,
      discountMinor: discountMinor,
      discountPercent: appliedDiscountPercent,
      taxMinor: cartTaxMinor,
      totalMinor: finalPayableMinor,
      savingsMinor: totalMrpSavingsMinor,
      selectedPayMode,
      status,
      splitDetails: selectedPayMode === 'split' ? {
        isSplit: true,
        method1: splitMethod1,
        amount1Minor: split1Minor,
        method2: splitMethod2,
        amount2Minor: split2Minor,
        hasUpi: hasUpiInSplit,
        upiAmountMinor: splitUpiMinor,
        otherMethod: otherSplitMethod,
        otherAmountMinor: otherSplitMinor,
      } : undefined,
      paymentDetails: status === 'completed' && checkoutSuccess ? {
        method: checkoutSuccess.payments?.[0]?.method || selectedPayMode || 'cash',
        amountMinor: checkoutSuccess.totalMinor || finalPayableMinor,
        changeDueMinor: checkoutSuccess.tender?.changeReturnedMinor || changeDueMinor || 0,
        invoiceNumber: checkoutSuccess.number || '',
      } : {
        method: (selectedPayMode === 'split' && hasUpiInSplit) ? 'upi' : (selectedPayMode || 'upi'),
        amountMinor: (selectedPayMode === 'split' && hasUpiInSplit) ? splitUpiMinor : finalPayableMinor,
        upiUrl,
      },
      updatedAt: Date.now(),
    };

    // 1. BroadcastChannel (0ms local dual-screen)
    try {
      bChannel?.postMessage(payload);
    } catch { }

    // 2. LocalStorage (multi-tab / multi-window)
    try {
      localStorage.setItem(`cfd_state_${counterId}`, JSON.stringify(payload));
    } catch { }

    // 3. Post to backend for remote wireless tablets
    const pushCfdState = () => {
      fetch('/api/cfd/update', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })
        .then((r) => r.json())
        .then((data) => {
          if (data?.isDisplayActive !== undefined) {
            setIsCfdConnected(Boolean(data.isDisplayActive));
          }
        })
        .catch(() => { });
    };

    pushCfdState();
    const syncInterval = setInterval(pushCfdState, 15000);

    return () => {
      bChannel?.close();
      clearInterval(syncInterval);
    };
  }, [
    cart,
    cartSubtotalMinor,
    cartTaxMinor,
    cartTaxableMinor,
    cartCgstMinor,
    cartSgstMinor,
    cartTotalMrpMinor,
    cartCategoryBreakdown,
    appliedDiscountPercent,
    discountMinor,
    totalMrpSavingsMinor,
    finalPayableMinor,
    selectedPartyId,
    parties,
    shop,
    user,
    selectedPayMode,
    splitMethod1,
    splitAmount1,
    splitMethod2,
    splitAmount2,
    split1Minor,
    split2Minor,
    changeDueMinor,
    checkoutSuccess,
  ]);

  const handleHoldOrder = () => {
    if (cart.length === 0) {
      if (heldOrders.length > 0) {
        const last = heldOrders[heldOrders.length - 1];
        setCart(last.cart);
        setHeldOrders((prev) => prev.slice(0, prev.length - 1));
        showToast(`Restored held order with ${last.cart.length} item(s)`);
      } else {
        showToast('Cart is empty. Nothing to hold.');
      }
      return;
    }
    setHeldOrders((prev) => [...prev, { id: Date.now().toString(), cart, timestamp: new Date() }]);
    setCart([]);
    showToast('Order held successfully! Click "Hold Order" anytime to restore.');
  };

  const handleReprintLastBill = () => {
    if (!invoices || invoices.length === 0) {
      showToast('No past bills available to reprint');
      return;
    }
    const lastRetail = invoices.find(inv => (inv.invoiceType || (inv as any).invoice_type) !== 'wholesale') || invoices[0];
    setPrintModalInvoiceId(lastRetail.id);
  };

  const handleAddCustomItem = (e: React.FormEvent) => {
    e.preventDefault();
    const priceNum = parseFloat(customItemForm.price);
    if (isNaN(priceNum) || priceNum <= 0) {
      showToast('Please enter a valid price');
      return;
    }
    const priceMinor = Math.round(priceNum * 100);
    const customItem: Item = {
      id: 'custom-' + Date.now(),
      name: customItemForm.name.trim() || 'Custom Charge',
      sku: 'CUSTOM',
      barcode: undefined,
      category: 'Service',
      priceMinor,
      costMinor: 0,
      taxRateBp: Number(customItemForm.taxRateBp) || 0,
      taxInclusive: false,
      hsn: '9983',
      unit: 'unit',
      currentStockMilli: 999999000,
      favorite: false,
      active: true,
    };
    addToCart(customItem);
    setShowCustomItemModal(false);
    showToast(`Added ${customItem.name} (${formatRupees(priceMinor)}) to cart`);
  };

  // Fast input focusing helpers for cashier keyboard shortcuts
  const focusProductSearch = () => {
    setShowProductCatalogDrawer(true);
    setTimeout(() => {
      if (catalogSearchInputRef.current) {
        catalogSearchInputRef.current.focus();
        catalogSearchInputRef.current.select();
      }
    }, 60);
  };

  const focusBarcodeScanner = () => {
    const el = document.getElementById('pos-product-search-input') as HTMLInputElement | null;
    if (el) {
      el.focus();
      el.select();
    } else if (catalogSearchInputRef.current) {
      catalogSearchInputRef.current.focus();
      catalogSearchInputRef.current.select();
    }
  };

  const focusCustomerMobile = () => {
    if (customerMobileInputRef.current) {
      customerMobileInputRef.current.focus();
      customerMobileInputRef.current.select();
    } else {
      setShowCustomerPickerModal(true);
    }
  };

  const focusCustomerName = () => {
    if (customerNameInputRef.current) {
      customerNameInputRef.current.focus();
      customerNameInputRef.current.select();
    } else {
      const el = (document.getElementById('pos-customer-name-input') ||
        document.getElementById('pos-quick-enroll-name-input')) as HTMLInputElement | null;
      if (el) {
        el.focus();
        el.select();
      }
    }
  };

  const focusProceedPayment = () => {
    if (checkoutBtnRef.current) {
      checkoutBtnRef.current.focus();
    } else {
      const el = document.getElementById('pos-proceed-payment-btn') as HTMLButtonElement | null;
      if (el) el.focus();
    }
  };

  const cyclePaymentMode = (direction: 'next' | 'prev') => {
    const modes: Array<'cash' | 'upi' | 'card' | 'bank' | 'split'> = ['cash', 'upi', 'card', 'bank', 'split'];
    const curIdx = modes.indexOf(selectedPayMode);
    const nextIdx = direction === 'next'
      ? (curIdx >= modes.length - 1 ? 0 : curIdx + 1)
      : (curIdx <= 0 ? modes.length - 1 : curIdx - 1);
    const nextMode = modes[nextIdx];
    setSelectedPayMode(nextMode);
    if (nextMode === 'split') {
      if (!splitAmount1 && !splitAmount2) {
        handleSplitFiftyFifty();
      } else if (parseFloat(splitAmount1 || '0') + parseFloat(splitAmount2 || '0') !== +(finalPayableMinor / 100).toFixed(2)) {
        handleSplitFiftyFifty();
      }
    }
    const labels: Record<string, string> = {
      cash: 'Payment: Cash',
      upi: 'Payment: Dynamic UPI QR',
      card: 'Payment: Card',
      bank: 'Payment: Bank Transfer',
      split: 'Payment: Split Payment',
    };
    showToast(labels[nextMode] || nextMode);
  };

  const handleQuickEnrollCustomer = async (phone: string, name?: string) => {
    const cleanDigits = phone.replace(/\D/g, '').slice(-10);
    if (!cleanDigits || cleanDigits.length < 7) {
      showToast('Please enter a valid mobile number (at least 7 to 10 digits)', 'warning');
      return;
    }
    setIsQuickEnrolling(true);
    try {
      const defaultName = (name && name.trim()) ? name.trim() : `Customer ${cleanDigits.slice(-4)}`;
      const res = await api<{ party: Party }>('/api/parties', {
        method: 'POST',
        body: JSON.stringify({
          name: defaultName,
          phone: cleanDigits,
          type: 'customer',
        }),
      });
      setParties((prev) => [res.party, ...prev]);
      setSelectedPartyId(res.party.id);
      setCustomerSearch(cleanDigits);
      setQuickCustomerName(res.party.name);
      customerNameManuallyEditedRef.current = false;
      setShowCustomerDropdown(false);
      showToast(`🎉 Customer ${res.party.name} enrolled! Points will start on this bill.`);
    } catch (err: any) {
      showToast(err.message || 'Failed to enroll customer', 'error');
    } finally {
      setIsQuickEnrolling(false);
    }
  };

  // Load shop-isolated payment settings
  useEffect(() => {
    if (!shop) return;
    getPaymentSettings()
      .then((cfg) => {
        setPosPaymentConfig(cfg);
        setPayUpiEnabled(cfg.upiEnabled);
        setPayQrType(cfg.qrType);
        setPayProvider(cfg.provider || (cfg.paytmEnabled ? 'paytm' : 'razorpay'));
        setPayStaticUpiId(cfg.staticUpiId || shop.upiId || '');
        setPayStaticMerchantName(cfg.staticMerchantName || shop.name || '');
        setPayRzpEnabled(cfg.rzpEnabled);
        setPayRzpMode(cfg.rzpMode);
        setPayRzpKeyId(cfg.rzpKeyId || '');
        setPayRzpExpiryMinutes(cfg.rzpQrExpiryMinutes || 15);
        setPayPaytmEnabled(Boolean(cfg.paytmEnabled));
        setPayPaytmMode(cfg.paytmMode || 'test');
        setPayPaytmMid(cfg.paytmMid || '');
        setPayPhonePeEnabled(Boolean(cfg.phonepeEnabled));
        setPayPhonePeMode(cfg.phonepeMode || 'test');
        setPayPhonePeMid(cfg.phonepeMid || '');
        setPayPhonePeSaltIndex(cfg.phonepeSaltIndex || '1');
        setPayPaytmWebsite(cfg.paytmWebsite || (cfg.paytmMode === 'live' ? 'DEFAULT' : 'WEBSTAGING'));
        setPayBankEnabled(Boolean(cfg.bankEnabled));
        setPayBankAccountName(cfg.bankAccountName || '');
        setPayBankAccountNo(cfg.bankAccountNo || '');
        setPayBankIfsc(cfg.bankIfsc || '');
        setPayBankName(cfg.bankName || '');
        setPayBankBranch(cfg.bankBranch || '');
        if (cfg.enabledMethods && Array.isArray(cfg.enabledMethods) && cfg.enabledMethods.length > 0) {
          setPayMethodsEnabled(cfg.enabledMethods);
          try {
            localStorage.setItem('pos_enabled_methods', JSON.stringify(cfg.enabledMethods));
          } catch { }
        }
        try {
          localStorage.setItem('pos_bank_enabled', String(Boolean(cfg.bankEnabled)));
          localStorage.setItem('pos_upi_enabled', String(Boolean(cfg.upiEnabled)));
        } catch { }
        if (cfg.upiEnabled === false && selectedPayMode === 'upi') {
          setSelectedPayMode('cash');
        }
        if (cfg.bankEnabled === false && selectedPayMode === 'bank') {
          setSelectedPayMode('cash');
        }
      })
      .catch((err) => {
        console.warn('Failed to load shop payment settings:', err);
      });
  }, [shop, activeTab]);

  // Dynamic QR auto-poll when status is pending
  useEffect(() => {
    if (!activeQrAttempt || activeQrAttempt.status !== 'pending' || activeQrAttempt.qrType !== 'dynamic') {
      return;
    }
    const timer = setInterval(async () => {
      try {
        const res = await getPaymentAttemptStatus(activeQrAttempt.attemptId);
        setActiveQrAttempt((prev) => prev ? {
          ...prev,
          status: res.status,
          providerPaymentId: res.providerPaymentId || prev.providerPaymentId,
        } : null);
        if (res.status === 'paid') {
          showToast('Payment verified successfully via UPI QR!');
        }
      } catch {
        // ignore background poll errors
      }
    }, 3000);
    return () => clearInterval(timer);
  }, [activeQrAttempt?.attemptId, activeQrAttempt?.status, activeQrAttempt?.qrType]);

  const handleGenerateDynamicQr = async () => {
    if (finalPayableMinor <= 0) {
      showToast('Cannot generate QR for ₹0 amount', 'error');
      return;
    }
    setIsGeneratingQr(true);
    try {
      const attempt = await createPaymentAttempt({
        amountMinor: finalPayableMinor,
        qrType: 'dynamic',
      });
      setActiveQrAttempt(attempt);
      showToast('Dynamic UPI QR generated!');
    } catch (err: any) {
      showToast(`Failed to generate Dynamic QR: ${err.message || 'Error'}`, 'error');
    } finally {
      setIsGeneratingQr(false);
    }
  };

  const handleVerifyDynamicQr = async () => {
    if (!activeQrAttempt) return;
    setIsVerifyingQr(true);
    try {
      const res = await verifyPaymentAttempt(activeQrAttempt.attemptId);
      setActiveQrAttempt((prev) => prev ? {
        ...prev,
        status: res.status as any,
        providerPaymentId: res.providerPaymentId || prev.providerPaymentId,
      } : null);
      if (res.status === 'paid') {
        showToast('Payment confirmed and verified!');
      } else {
        showToast(`Payment status: ${res.status}`);
      }
    } catch (err: any) {
      showToast(`Verification: ${err.message || 'Status check failed'}`, 'error');
    } finally {
      setIsVerifyingQr(false);
    }
  };

  const handleSavePaymentSettings = async (
    e?: React.FormEvent,
    customOverrides?: Partial<PublicPaymentSettings>,
    silent: boolean = false
  ) => {
    if (e) e.preventDefault();
    if (!user || user.role === 'cashier') {
      showToast('Only Owner or Store Manager can modify payment settings', 'error');
      return;
    }
    setIsSavingPaySettings(true);
    if (!silent) setPaySettingsStatusMsg(null);
    try {
      const bankActive = customOverrides?.bankEnabled !== undefined ? customOverrides.bankEnabled : payBankEnabled;
      const methodsActive = customOverrides?.enabledMethods !== undefined ? customOverrides.enabledMethods : payMethodsEnabled;
      const rzpActive = customOverrides?.rzpEnabled !== undefined ? customOverrides.rzpEnabled : payRzpEnabled;
      const upiActive = customOverrides?.upiEnabled !== undefined ? customOverrides.upiEnabled : methodsActive.includes('upi');

      const updated = await updatePaymentSettings({
        upiEnabled: upiActive,
        qrType: customOverrides?.qrType !== undefined ? customOverrides.qrType : payQrType,
        provider: customOverrides?.provider !== undefined
          ? customOverrides.provider
          : (payQrType === 'dynamic' ? payProvider : (rzpActive ? 'razorpay' : payPaytmEnabled ? 'paytm' : 'manual')),
        staticUpiId: ((customOverrides?.staticUpiId !== undefined ? customOverrides.staticUpiId : payStaticUpiId) || '').trim() || null,
        staticMerchantName: ((customOverrides?.staticMerchantName !== undefined ? customOverrides.staticMerchantName : payStaticMerchantName) || '').trim() || null,
        rzpEnabled: rzpActive,
        rzpMode: customOverrides?.rzpMode !== undefined ? customOverrides.rzpMode : payRzpMode,
        rzpKeyId: ((customOverrides?.rzpKeyId !== undefined ? customOverrides.rzpKeyId : payRzpKeyId) || '').trim() || null,
        rzpKeySecret: payRzpKeySecret.trim() ? payRzpKeySecret.trim() : undefined,
        rzpWebhookSecret: payRzpWebhookSecret.trim() ? payRzpWebhookSecret.trim() : undefined,
        rzpQrExpiryMinutes: Number(payRzpExpiryMinutes) || 15,
        paytmEnabled: customOverrides?.paytmEnabled !== undefined ? customOverrides.paytmEnabled : payPaytmEnabled,
        paytmMode: customOverrides?.paytmMode !== undefined ? customOverrides.paytmMode : payPaytmMode,
        paytmMid: ((customOverrides?.paytmMid !== undefined ? customOverrides.paytmMid : payPaytmMid) || '').trim() || null,
        paytmMerchantKey: payPaytmMerchantKey.trim() ? payPaytmMerchantKey.trim() : undefined,
        paytmWebsite: payPaytmWebsite.trim() || (payPaytmMode === 'live' ? 'DEFAULT' : 'WEBSTAGING'),
        phonepeEnabled: customOverrides?.phonepeEnabled !== undefined ? customOverrides.phonepeEnabled : payPhonePeEnabled,
        phonepeMode: customOverrides?.phonepeMode !== undefined ? customOverrides.phonepeMode : payPhonePeMode,
        phonepeMid: ((customOverrides?.phonepeMid !== undefined ? customOverrides.phonepeMid : payPhonePeMid) || '').trim() || null,
        phonepeSaltKey: payPhonePeSaltKey.trim() ? payPhonePeSaltKey.trim() : undefined,
        phonepeSaltIndex: payPhonePeSaltIndex.trim() || '1',
        bankEnabled: bankActive,
        bankAccountName: ((customOverrides?.bankAccountName !== undefined ? customOverrides.bankAccountName : payBankAccountName) || '').trim() || null,
        bankAccountNo: ((customOverrides?.bankAccountNo !== undefined ? customOverrides.bankAccountNo : payBankAccountNo) || '').trim() || null,
        bankIfsc: ((customOverrides?.bankIfsc !== undefined ? customOverrides.bankIfsc : payBankIfsc) || '').trim() || null,
        bankName: ((customOverrides?.bankName !== undefined ? customOverrides.bankName : payBankName) || '').trim() || null,
        bankBranch: ((customOverrides?.bankBranch !== undefined ? customOverrides.bankBranch : payBankBranch) || '').trim() || null,
        enabledMethods: bankActive
          ? Array.from(new Set([...methodsActive, 'bank']))
          : methodsActive.filter((m) => m !== 'bank'),
      });

      setPosPaymentConfig(updated);
      setActiveQrAttempt(null);
      if (updated.staticUpiId && shop) {
        setShop((prev) => prev ? { ...prev, upiId: updated.staticUpiId || prev.upiId } : null);
      }
      setPayRzpKeySecret('');
      setPayRzpWebhookSecret('');
      setPayPaytmMerchantKey('');
      setPayPhonePeSaltKey('');
      if (!silent) {
        setPaySettingsStatusMsg({
          type: 'success',
          text: `Payment settings saved successfully! Status: ${updated.status === 'connected' ? 'Connected' : updated.status === 'error' ? 'Validation Error' : 'Configured'}`
        });
        showToast(`Payment settings saved (${updated.status})`);
      } else {
        showToast('Payment settings saved');
      }
    } catch (err: any) {
      if (!silent) {
        setPaySettingsStatusMsg({
          type: 'error',
          text: err.message || 'Failed to update payment settings',
        });
      }
      showToast(err.message || 'Failed to save payment settings', 'error');
    } finally {
      setIsSavingPaySettings(false);
    }
  };

  const handleSavePaymentMethods = async (
    customMethods?: string[],
    customBank?: boolean,
    silent: boolean = false
  ) => {
    if (!user || user.role === 'cashier') {
      showToast('Only Owner or Store Manager can modify payment methods', 'error');
      return;
    }
    if (!silent) {
      setIsSavingMethods(true);
    }
    try {
      const methodsActive = customMethods !== undefined ? customMethods : payMethodsEnabled;
      const bankActive = customBank !== undefined ? customBank : payBankEnabled;
      const upiActive = methodsActive.includes('upi');

      const methodsPayload = bankActive
        ? Array.from(new Set([...methodsActive, 'bank']))
        : methodsActive.filter((m) => m !== 'bank');

      // Instantly cache in localStorage so any page refresh is instantaneous (0 delay)
      try {
        localStorage.setItem('pos_enabled_methods', JSON.stringify(methodsPayload));
        localStorage.setItem('pos_bank_enabled', String(bankActive));
        localStorage.setItem('pos_upi_enabled', String(upiActive));
      } catch { }

      const updated = await updatePaymentSettings({
        target: 'methods',
        enabledMethods: methodsPayload,
        bankEnabled: bankActive,
        upiEnabled: upiActive,
      });

      setPosPaymentConfig(updated);
      if (updated.enabledMethods && Array.isArray(updated.enabledMethods)) {
        setPayMethodsEnabled(updated.enabledMethods);
      }
      setPayBankEnabled(Boolean(updated.bankEnabled));
      setPayUpiEnabled(Boolean(updated.upiEnabled));

      if (!silent) {
        showToast('Payment methods saved successfully');
      }
    } catch (err: any) {
      if (!silent) {
        showToast(err.message || 'Failed to save payment methods', 'error');
      }
    } finally {
      if (!silent) {
        setIsSavingMethods(false);
      }
    }
  };

  const handleTogglePaymentMethod = async (methodId: string) => {
    if (!user || user.role === 'cashier') {
      showToast('Only Owner or Store Manager can modify payment methods', 'error');
      return;
    }
    if (methodId === 'cash') return; // Cash cannot be disabled

    let nextBank = payBankEnabled;
    let nextMethods = [...payMethodsEnabled];

    if (methodId === 'bank') {
      nextBank = !payBankEnabled;
      setPayBankEnabled(nextBank);
      if (nextBank) {
        nextMethods = Array.from(new Set([...nextMethods, 'bank']));
      } else {
        nextMethods = nextMethods.filter((m) => m !== 'bank');
      }
    } else {
      const isChecked = payMethodsEnabled.includes(methodId);
      if (isChecked) {
        nextMethods = nextMethods.filter((m) => m !== methodId);
      } else {
        nextMethods = Array.from(new Set([...nextMethods, methodId]));
      }
      if (methodId === 'upi') {
        setPayUpiEnabled(nextMethods.includes('upi'));
      }
    }
    setPayMethodsEnabled(nextMethods);

    // Save to localStorage immediately so browser refresh never reverts
    try {
      localStorage.setItem('pos_enabled_methods', JSON.stringify(nextMethods));
      localStorage.setItem('pos_bank_enabled', String(nextBank));
      localStorage.setItem('pos_upi_enabled', String(nextMethods.includes('upi')));
    } catch { }

    // Auto-save silently in background without locking the button
    await handleSavePaymentMethods(nextMethods, nextBank, true);
  };

