                              border: '1px solid #cbd5e1',
                              color: '#334155',
                              padding: '0.35rem 0.65rem',
                              borderRadius: '8px',
                              fontSize: '0.76rem',
                              fontWeight: 700,
                              cursor: 'pointer',
                              display: 'inline-flex',
                              alignItems: 'center',
                              gap: '4px',
